use vstd::prelude::*;

verus! {
    /// Reverse a Vec<i32>.
    ///
    /// Ensures: the returned vector has the same length as `a`, and
    /// for all 0 <= i < a.len(), a[i] == result[a.len() - 1 - i].
    pub fn reverse(a: &Vec<i32>) -> Vec<i32>
        ensures |r: &Vec<i32>|
            // same length
            r.len() == a.len()
            // reversed content
            && forall |i: usize|
                 i < a.len() ==> a[i] == r[a.len() - 1 - i]
    {
        let n: usize = a.len();
        let mut res: Vec<i32> = Vec::new();
        let mut i: usize = 0;
        // Build res by appending a[n-1-i] for i = 0..n
        while i < n
            invariant i <= n
            invariant res.len() == i
            invariant forall |j: usize|
                j < i ==> res[j] == a[n - 1 - j]
            decreases n - i
        {
            // safe because i < n ensures (n - 1 - i) < n
            res.push(a[n - 1 - i]);
            i += 1;
        }
        res
    }
}